-- King of Chips 2.0 production schema
create extension if not exists pgcrypto;
create table if not exists public.profiles(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,role text not null default 'participant' check(role in ('participant','admin')),created_at timestamptz not null default now());
create table if not exists public.tournaments(id uuid primary key default gen_random_uuid(),name text not null default 'King of Chips 2.0',status text not null default 'registration' check(status in ('registration','ready','live','completed')),starting_stack int not null default 1000 check(starting_stack>0),small_blind int not null default 10 check(small_blind>0),big_blind int not null default 20 check(big_blind>=small_blind),hands_per_room int not null default 3 check(hands_per_room between 1 and 10),room_capacity int not null default 6 check(room_capacity between 2 and 10),qualifiers int not null default 18 check(qualifiers>0),created_at timestamptz not null default now());
create table if not exists public.teams(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,team_name text not null,captain_name text not null,owner_user_id uuid not null references auth.users(id),room_id uuid,chip_stack int not null default 1000 check(chip_stack>=0),highest_pot_won int not null default 0,status text not null default 'registered' check(status in ('registered','playing','finished','disqualified')),created_at timestamptz not null default now(),unique(tournament_id,team_name),unique(owner_user_id,tournament_id));
create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments(id) on delete cascade,room_number int not null,hand_number int not null default 0 check(hand_number between 0 and 10),status text not null default 'ready' check(status in ('ready','playing','completed')),created_at timestamptz not null default now(),unique(tournament_id,room_number));
alter table public.teams drop constraint if exists teams_room_id_fkey;
alter table public.teams add constraint teams_room_id_fkey foreign key(room_id) references public.rooms(id) on delete set null;
create table if not exists public.hands(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,hand_number int not null check(hand_number between 1 and 10),status text not null default 'preflop' check(status in ('preflop','flop','turn','river','settled')),pot_total int not null default 0,current_bet int not null default 0,min_raise int not null default 20,board jsonb not null default '[]',dealer_seat int not null default 0,turn_seat int not null default 0,deck jsonb not null default '[]',action_deadline timestamptz,last_action text,result jsonb not null default '[]',started_at timestamptz not null default now(),settled_at timestamptz,unique(room_id,hand_number));
create table if not exists public.hand_players(id uuid primary key default gen_random_uuid(),hand_id uuid not null references public.hands(id) on delete cascade,team_id uuid not null references public.teams(id) on delete cascade,seat_number int not null,hole_cards jsonb not null default '[]',stack_start int not null,stack_current int not null,street_bet int not null default 0,contribution int not null default 0,folded boolean not null default false,all_in boolean not null default false,acted boolean not null default false,unique(hand_id,team_id),unique(hand_id,seat_number));
create table if not exists public.hand_actions(id uuid primary key default gen_random_uuid(),hand_id uuid not null references public.hands(id) on delete cascade,team_id uuid not null references public.teams(id) on delete cascade,action_number int not null,action text not null,amount int not null default 0,created_at timestamptz not null default now(),unique(hand_id,action_number));
create index if not exists teams_tournament_room_idx on public.teams(tournament_id,room_id);
create index if not exists teams_room_id_idx on public.teams(room_id);
create index if not exists hand_players_hand_idx on public.hand_players(hand_id);
create index if not exists hand_players_team_id_idx on public.hand_players(team_id);
create index if not exists hand_actions_hand_idx on public.hand_actions(hand_id);
create index if not exists hand_actions_team_id_idx on public.hand_actions(team_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(user_id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict(user_id) do nothing; return new; end $$;
drop trigger if exists on_auth_user_created_koc on auth.users;
create trigger on_auth_user_created_koc after insert on auth.users for each row execute procedure public.handle_new_user();
insert into public.tournaments(name) select 'King of Chips 2.0' where not exists(select 1 from public.tournaments);
alter table public.profiles enable row level security;
alter table public.tournaments enable row level security;
alter table public.teams enable row level security;
alter table public.rooms enable row level security;
alter table public.hands enable row level security;
alter table public.hand_players enable row level security;
alter table public.hand_actions enable row level security;
drop policy if exists "profile self read" on public.profiles;
create policy "profile self read" on public.profiles for select to authenticated using(user_id=(select auth.uid()));
drop policy if exists "profile self update" on public.profiles;
create policy "profile self update" on public.profiles for update to authenticated using(user_id=(select auth.uid())) with check(user_id=(select auth.uid()) and role='participant');
drop policy if exists "tournament authenticated read" on public.tournaments;
create policy "tournament authenticated read" on public.tournaments for select to authenticated using(true);
drop policy if exists "teams authenticated read" on public.teams;
create policy "teams authenticated read" on public.teams for select to authenticated using(true);
drop policy if exists "rooms authenticated read" on public.rooms;
create policy "rooms authenticated read" on public.rooms for select to authenticated using(true);
drop policy if exists "hands authenticated read" on public.hands;
create policy "hands authenticated read" on public.hands for select to authenticated using(true);
drop policy if exists "hand player own cards" on public.hand_players;
create policy "hand player own cards" on public.hand_players for select to authenticated using(team_id in (select id from public.teams where owner_user_id=(select auth.uid())));
drop policy if exists "actions authenticated read" on public.hand_actions;
create policy "actions authenticated read" on public.hand_actions for select to authenticated using(true);
grant usage on schema public to anon,authenticated;
grant select,update on public.profiles to authenticated;
grant select on public.tournaments,public.rooms,public.hand_actions,public.hand_players to authenticated;
grant select on public.teams to authenticated;
grant select on public.hands to authenticated;
revoke execute on function public.handle_new_user() from public,anon,authenticated;
revoke select on public.hands from authenticated;
grant select(id,room_id,hand_number,status,pot_total,current_bet,min_raise,board,dealer_seat,turn_seat,action_deadline,last_action,result,started_at,settled_at) on public.hands to authenticated;
revoke select on public.teams from authenticated;
grant select(id,tournament_id,team_name,captain_name,room_id,chip_stack,highest_pot_won,status,created_at) on public.teams to authenticated;
do $$ declare t text; begin foreach t in array array['teams','rooms','hands','hand_players','hand_actions','tournaments'] loop if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename=t) then execute format('alter publication supabase_realtime add table public.%I',t); end if; end loop; end $$;
